INSERT INTO public.menu_items (
  id, subcategory_id, name, name_bs, name_ar,
  description, description_bs, description_ar,
  price, is_available, station, allergens, dietary_tags,
  meal_role, sort_order, image_url,
  featured_rank, featured_note, featured_note_bs, featured_note_ar
) VALUES
  ('b7a1d000-0000-4000-8000-000000000001', 'b7a15000-0000-4000-8000-000000000011', 'Bruschetta', 'Bruschetta', 'بروسكيتا', 'Toasted baguette rubbed with garlic, olive oil and parmesan, crowned with diced tomato, garlic, basil and cracked black pepper, finished with extra virgin olive oil and balsamic glaze.', 'Prepečeni baguette natrljan bijelim lukom, maslinovim uljem i parmezanom, s kockicama paradajza, bijelim lukom, bosiljkom i svježe mljevenim biberom, završen ekstra djevičanskim maslinovim uljem i balzamiko glazurom.', 'خبز باغيت محمّص مدهون بالثوم وزيت الزيتون والبارميزان، تعلوه مكعبات الطماطم والثوم والريحان والفلفل الأسود المطحون، مع زيت زيتون بكر ممتاز وصلصة البلسميك.', 11.00, true, 'kitchen', ARRAY['gluten', 'dairy', 'sulphites']::text[], ARRAY['vegetarian']::text[], 'starter'::public.meal_role, 1, '/menu/b7a1d000-0000-4000-8000-000000000001/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000002', 'b7a15000-0000-4000-8000-000000000011', 'Baked Feta Dip', 'Zapečeni feta dip', 'غموس الفيتا المخبوز', 'Creamy feta and cream cheese baked with cherry tomatoes, green and black olives and herbs in olive oil, with garlic-toasted baguette and parmesan.', 'Kremasti feta i krem-sir zapečeni s čeri paradajzom, zelenim i crnim maslinama i začinskim biljem u maslinovom ulju, uz prepečeni baguette s bijelim lukom i parmezanom.', 'جبن فيتا كريمي مع جبن كريمي مخبوزان مع الطماطم الكرزية والزيتون الأخضر والأسود والأعشاب بزيت الزيتون، يُقدَّمان مع باغيت محمّص بالثوم والبارميزان.', 12.50, true, 'kitchen', ARRAY['gluten', 'dairy']::text[], ARRAY['vegetarian']::text[], 'starter'::public.meal_role, 2, '/menu/b7a1d000-0000-4000-8000-000000000002/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000003', 'b7a15000-0000-4000-8000-000000000012', 'Insalata Caprese', 'Insalata Caprese', 'سلطة كابريزي', 'Whole-milk mozzarella and ripe tomato with fresh basil, sea salt and black pepper, extra virgin olive oil and balsamic glaze.', 'Mocarela od punomasnog mlijeka i zreli paradajz sa svježim bosiljkom, morskom solju i biberom, ekstra djevičanskim maslinovim uljem i balzamiko glazurom.', 'موزاريلا من الحليب كامل الدسم وطماطم ناضجة مع ريحان طازج وملح بحري وفلفل أسود، زيت زيتون بكر ممتاز وصلصة البلسميك.', 14.00, true, 'kitchen', ARRAY['dairy', 'sulphites']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 'starter'::public.meal_role, 1, '/menu/b7a1d000-0000-4000-8000-000000000003/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000004', 'b7a15000-0000-4000-8000-000000000012', 'Grilled Vegetable Salad', 'Salata od grilovanog povrća', 'سلطة الخضار المشوية', 'Grilled bell peppers and red onion over rocket, radicchio and iceberg, dressed in balsamic and finished with crumbled feta.', 'Grilovane paprike i crveni luk na rukoli, radiču i ajsbergu, s balzamiko dresingom i izmrvljenim feta sirom.', 'فلفل حلو وبصل أحمر مشويان على الجرجير والراديكيو والخس، بصلصة البلسميك مع فتات جبن الفيتا.', 10.00, true, 'kitchen', ARRAY['dairy', 'sulphites']::text[], ARRAY['vegetarian', 'gluten_free']::text[], 'starter'::public.meal_role, 2, '/menu/b7a1d000-0000-4000-8000-000000000004/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000005', 'b7a15000-0000-4000-8000-000000000021', 'Penne all''Arrabbiata', 'Penne all''Arrabbiata', 'بيني أرابياتا', 'Penne in a fiery tomato arrabbiata sauce with shaved parmesan and fresh herbs.', 'Penne u ljutom paradajz sosu arrabbiata s listićima parmezana i svježim biljem.', 'بيني بصلصة الطماطم الأرابياتا الحارة مع رقائق البارميزان والأعشاب الطازجة.', 7.00, true, 'kitchen', ARRAY['gluten', 'dairy']::text[], ARRAY['vegetarian', 'spicy']::text[], 'main'::public.meal_role, 1, '/menu/b7a1d000-0000-4000-8000-000000000005/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000006', 'b7a15000-0000-4000-8000-000000000021', 'Pesto Alfredo Fettuccine', 'Fettuccine Alfredo s pestom', 'فيتوتشيني ألفريدو بالبيستو', 'Fettuccine in a creamy basil-pesto alfredo with grated parmesan and fresh herbs.', 'Fettuccine u kremastom alfredo sosu s pestom od bosiljka, rendanim parmezanom i svježim biljem.', 'فيتوتشيني بصلصة ألفريدو الكريمية مع بيستو الريحان والبارميزان المبشور والأعشاب الطازجة.', 13.00, true, 'kitchen', ARRAY['gluten', 'dairy', 'nuts']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 2, '/menu/b7a1d000-0000-4000-8000-000000000006/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000007', 'b7a15000-0000-4000-8000-000000000021', 'Mushroom Alfredo Fettuccine', 'Fettuccine Alfredo s gljivama', 'فيتوتشيني ألفريدو بالفطر', 'Fettuccine in a silky alfredo sauce with grilled mushrooms, grated parmesan and fresh herbs.', 'Fettuccine u svilenkastom alfredo sosu s grilovanim gljivama, rendanim parmezanom i svježim biljem.', 'فيتوتشيني بصلصة ألفريدو الناعمة مع الفطر المشوي والبارميزان المبشور والأعشاب الطازجة.', 10.50, true, 'kitchen', ARRAY['gluten', 'dairy']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 3, '/menu/b7a1d000-0000-4000-8000-000000000007/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000008', 'b7a15000-0000-4000-8000-000000000021', 'Truffle Pasta', 'Pasta s tartufom', 'باستا الكمأة', 'Fettuccine in a creamy alfredo sauce with black truffle paste and grated parmesan.', 'Fettuccine u kremastom alfredo sosu s pastom od crnog tartufa i rendanim parmezanom.', 'فيتوتشيني بصلصة ألفريدو الكريمية مع معجون الكمأة السوداء والبارميزان المبشور.', 13.00, true, 'kitchen', ARRAY['gluten', 'dairy']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 4, '/menu/b7a1d000-0000-4000-8000-000000000008/1152.webp', 3, 'Black truffle, folded into alfredo', 'Crni tartuf u alfredo sosu', 'كمأة سوداء في صلصة ألفريدو'),
  ('b7a1d000-0000-4000-8000-000000000009', 'b7a15000-0000-4000-8000-000000000021', 'Eggplant & Truffle Spaghetti', 'Špageti s patlidžanom i tartufom', 'سباغيتي الباذنجان والكمأة', 'Spaghetti in a creamy rosé sauce with truffle paste, topped with crisp fried eggplant and parmesan.', 'Špageti u kremastom roze sosu s pastom od tartufa, preliveni hrskavim prženim patlidžanom i parmezanom.', 'سباغيتي بصلصة وردية كريمية مع معجون الكمأة، تعلوها شرائح باذنجان مقلية مقرمشة والبارميزان.', 14.00, true, 'kitchen', ARRAY['gluten', 'dairy']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 5, '/menu/b7a1d000-0000-4000-8000-000000000009/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000010', 'b7a15000-0000-4000-8000-000000000022', 'Pesto Risotto', 'Rižoto s pestom', 'ريزوتو بالبيستو', 'Creamy risotto with alfredo and basil pesto, finished with fresh herbs.', 'Kremasti rižoto s alfredo sosom i pestom od bosiljka, završen svježim biljem.', 'ريزوتو كريمي بصلصة ألفريدو وبيستو الريحان مع الأعشاب الطازجة.', 15.00, true, 'kitchen', ARRAY['dairy', 'nuts']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 1, '/menu/b7a1d000-0000-4000-8000-000000000010/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000011', 'b7a15000-0000-4000-8000-000000000022', 'Mushroom Risotto', 'Rižoto s gljivama', 'ريزوتو بالفطر', 'Creamy risotto in a white alfredo sauce with grilled button mushrooms and fresh herbs.', 'Kremasti rižoto u bijelom alfredo sosu s grilovanim šampinjonima i svježim biljem.', 'ريزوتو كريمي بصلصة ألفريدو البيضاء مع فطر المشروم المشوي والأعشاب الطازجة.', 14.00, true, 'kitchen', ARRAY['dairy']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 2, '/menu/b7a1d000-0000-4000-8000-000000000011/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000012', 'b7a15000-0000-4000-8000-000000000022', 'Truffle Risotto', 'Rižoto s tartufom', 'ريزوتو الكمأة', 'Creamy alfredo risotto with black truffle paste, finished with fresh herbs.', 'Kremasti alfredo rižoto s pastom od crnog tartufa, završen svježim biljem.', 'ريزوتو ألفريدو كريمي مع معجون الكمأة السوداء والأعشاب الطازجة.', 15.00, true, 'kitchen', ARRAY['dairy']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 3, '/menu/b7a1d000-0000-4000-8000-000000000012/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000013', 'b7a15000-0000-4000-8000-000000000022', 'Pink Sauce Risotto', 'Rižoto u roze sosu', 'ريزوتو بالصلصة الوردية', 'Risotto in a creamy rosé sauce with cherry tomatoes, black olives and a drizzle of balsamic cream.', 'Rižoto u kremastom roze sosu s čeri paradajzom, crnim maslinama i balzamiko kremom.', 'ريزوتو بصلصة وردية كريمية مع الطماطم الكرزية والزيتون الأسود ورشّة من كريمة البلسميك.', 15.00, true, 'kitchen', ARRAY['dairy', 'sulphites']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 4, '/menu/b7a1d000-0000-4000-8000-000000000013/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000014', 'b7a15000-0000-4000-8000-000000000023', 'Grilled Chicken', 'Grilovana piletina', 'دجاج مشوي', 'Add sliced grilled chicken to any pasta or risotto.', 'Dodajte grilovanu piletinu bilo kojoj pasti ili rižotu.', 'أضف شرائح الدجاج المشوي إلى أي طبق باستا أو ريزوتو.', 2.00, true, 'kitchen', '{}'::text[], ARRAY['gluten_free', 'dairy_free']::text[], 'side'::public.meal_role, 1, NULL, NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000015', 'b7a15000-0000-4000-8000-000000000031', 'Margherita', 'Margherita', 'مارغريتا', 'Neapolitan dough, tomato sauce, fior di latte, parmesan and fresh basil, finished with oregano and extra virgin olive oil.', 'Napolitansko tijesto, paradajz sos, fior di latte, parmezan i svježi bosiljak, završeno origanom i ekstra djevičanskim maslinovim uljem.', 'عجينة نابوليتانية، صلصة طماطم، موزاريلا فيور دي لاتيه، بارميزان وريحان طازج، مع الأوريغانو وزيت الزيتون البكر الممتاز.', 15.00, true, 'kitchen', ARRAY['gluten', 'dairy']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 1, '/menu/b7a1d000-0000-4000-8000-000000000015/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000016', 'b7a15000-0000-4000-8000-000000000031', 'Pepperoni', 'Pepperoni', 'بيبروني', 'Neapolitan dough, tomato sauce, fior di latte, pepperoni and parmesan.', 'Napolitansko tijesto, paradajz sos, fior di latte, pepperoni i parmezan.', 'عجينة نابوليتانية، صلصة طماطم، موزاريلا فيور دي لاتيه، بيبروني وبارميزان.', 15.00, true, 'kitchen', ARRAY['gluten', 'dairy']::text[], '{}'::text[], 'main'::public.meal_role, 2, '/menu/b7a1d000-0000-4000-8000-000000000016/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000017', 'b7a15000-0000-4000-8000-000000000031', 'Quattro Formaggi', 'Quattro Formaggi', 'كواترو فورماجي', 'White cream, fior di latte, gorgonzola, edam and grana padano, the crust brushed with extra virgin olive oil.', 'Bijeli krem sos, fior di latte, gorgonzola, edamer i grana padano, rub premazan ekstra djevičanskim maslinovim uljem.', 'صلصة كريمة بيضاء، فيور دي لاتيه، غورغونزولا، إيدام وغرانا بادانو، مع حافة مدهونة بزيت الزيتون البكر الممتاز.', 15.00, true, 'kitchen', ARRAY['gluten', 'dairy']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 3, '/menu/b7a1d000-0000-4000-8000-000000000017/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000018', 'b7a15000-0000-4000-8000-000000000031', 'Burrata Pizza', 'Pizza s burratom', 'بيتزا البوراتا', 'White cream, fior di latte, burrata, basil pesto and cherry tomatoes, finished with black pepper, sea salt and extra virgin olive oil.', 'Bijeli krem sos, fior di latte, burrata, pesto od bosiljka i čeri paradajz, završeno crnim biberom, morskom solju i ekstra djevičanskim maslinovim uljem.', 'صلصة كريمة بيضاء، فيور دي لاتيه، جبن البوراتا، بيستو الريحان والطماطم الكرزية، مع الفلفل الأسود وملح البحر وزيت الزيتون البكر الممتاز.', 24.50, true, 'kitchen', ARRAY['gluten', 'dairy', 'nuts']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 4, '/menu/b7a1d000-0000-4000-8000-000000000018/1152.webp', 2, 'Burrata, pesto and cherry tomatoes', 'Burrata, pesto i čeri paradajz', 'بوراتا وبيستو وطماطم كرزية'),
  ('b7a1d000-0000-4000-8000-000000000019', 'b7a15000-0000-4000-8000-000000000032', 'Truffle Pizza', 'Pizza s tartufom', 'بيتزا الكمأة', 'White cream, fior di latte, sautéed and button mushrooms and truffle cream, finished with parmesan, truffle oil and freshly grated truffle.', 'Bijeli krem sos, fior di latte, pirjane gljive i šampinjoni te krem od tartufa, završeno parmezanom, uljem od tartufa i svježe rendanim tartufom.', 'صلصة كريمة بيضاء، فيور دي لاتيه، فطر مطهو وفطر المشروم وكريمة الكمأة، مع البارميزان وزيت الكمأة والكمأة المبشورة طازجة.', 25.00, true, 'kitchen', ARRAY['gluten', 'dairy']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 1, '/menu/b7a1d000-0000-4000-8000-000000000019/1152.webp', 1, 'Freshly grated truffle, from the oven', 'Svježe rendani tartuf, iz peći', 'كمأة مبشورة طازجة من الفرن'),
  ('b7a1d000-0000-4000-8000-000000000020', 'b7a15000-0000-4000-8000-000000000032', 'Ricotta & Honey Pizza', 'Pizza s rikotom i medom', 'بيتزا الريكوتا والعسل', 'White cream, fior di latte and ricotta, finished with honey and chopped walnuts.', 'Bijeli krem sos, fior di latte i rikota, završeno medom i sjeckanim orasima.', 'صلصة كريمة بيضاء، فيور دي لاتيه وريكوتا، مع العسل والجوز المفروم.', 17.50, true, 'kitchen', ARRAY['gluten', 'dairy', 'nuts']::text[], ARRAY['vegetarian', 'contains_nuts']::text[], 'main'::public.meal_role, 2, '/menu/b7a1d000-0000-4000-8000-000000000020/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000021', 'b7a15000-0000-4000-8000-000000000032', 'Short Rib Pizza', 'Pizza s junećim rebrima', 'بيتزا الضلوع البقرية', 'BBQ sauce, fior di latte and tender beef short rib, finished with shaved grana padano.', 'BBQ sos, fior di latte i mekana juneća rebra, završeno listićima grana padana.', 'صلصة باربكيو، فيور دي لاتيه وضلوع بقر طرية، مع رقائق غرانا بادانو.', 25.00, true, 'kitchen', ARRAY['gluten', 'dairy']::text[], '{}'::text[], 'main'::public.meal_role, 3, '/menu/b7a1d000-0000-4000-8000-000000000021/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000022', 'b7a15000-0000-4000-8000-000000000032', 'Musakhan Pizza', 'Musakhan pizza', 'بيتزا المسخّن', 'White cream, fior di latte, house musakhan chicken and caramelised onion, finished with yoghurt, pomegranate seeds and pomegranate molasses.', 'Bijeli krem sos, fior di latte, piletina musakhan po kućnom receptu i karamelizirani luk, završeno jogurtom, zrnima nara i melasom od nara.', 'صلصة كريمة بيضاء، فيور دي لاتيه، دجاج مسخّن على طريقة البيت وبصل مكرمل، مع اللبن وحبوب الرمان ودبس الرمان.', 22.50, true, 'kitchen', ARRAY['gluten', 'dairy']::text[], '{}'::text[], 'main'::public.meal_role, 4, '/menu/b7a1d000-0000-4000-8000-000000000022/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000023', 'b7a15000-0000-4000-8000-000000000032', 'Za''atar Pizza', 'Za''atar pizza', 'بيتزا الزعتر', 'White cream, fior di latte and za''atar with pomegranate seeds, cream cheese and rocket, the crust brushed with extra virgin olive oil.', 'Bijeli krem sos, fior di latte i za''atar sa zrnima nara, krem-sirom i rukolom, rub premazan ekstra djevičanskim maslinovim uljem.', 'صلصة كريمة بيضاء، فيور دي لاتيه والزعتر مع حبوب الرمان والجبن الكريمي والجرجير، وحافة مدهونة بزيت الزيتون البكر الممتاز.', 14.50, true, 'kitchen', ARRAY['gluten', 'dairy', 'sesame']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 5, '/menu/b7a1d000-0000-4000-8000-000000000023/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000024', 'b7a15000-0000-4000-8000-000000000032', 'Egg & Spinach Pizza', 'Pizza s jajem i špinatom', 'بيتزا البيض والسبانخ', 'White cream, fior di latte, spinach, egg and hollandaise, the crust brushed with extra virgin olive oil.', 'Bijeli krem sos, fior di latte, špinat, jaje i holandez sos, rub premazan ekstra djevičanskim maslinovim uljem.', 'صلصة كريمة بيضاء، فيور دي لاتيه، سبانخ وبيض وصلصة هولنديز، مع حافة مدهونة بزيت الزيتون البكر الممتاز.', 12.00, true, 'kitchen', ARRAY['gluten', 'dairy', 'eggs']::text[], ARRAY['vegetarian']::text[], 'main'::public.meal_role, 6, '/menu/b7a1d000-0000-4000-8000-000000000024/1152.webp', NULL, NULL, NULL, NULL),
  ('b7a1d000-0000-4000-8000-000000000025', 'b7a15000-0000-4000-8000-000000000041', 'Rib-eye Steak Platter', 'Rib-eye steak plata', 'طبق ستيك ريب آي', 'Rib-eye steak with the famous entrecôte sauce, served with fries in entrecôte sauce, a walnut salad of iceberg and radicchio with Caesar dressing and candied walnuts, and toasted baguette.', 'Rib-eye steak s čuvenim entrecôte sosom, uz pomfrit u entrecôte sosu, salatu od ajsberga i radiča s Cezar dresingom i karameliziranim orasima te prepečeni baguette.', 'ستيك ريب آي بصلصة الأنتريكوت الشهيرة، يُقدَّم مع بطاطا مقلية بصلصة الأنتريكوت، وسلطة الجوز من الخس والراديكيو بصلصة السيزر والجوز المكرمل، وخبز باغيت محمّص.', 64.00, true, 'kitchen', ARRAY['gluten', 'dairy', 'eggs', 'nuts']::text[], ARRAY['contains_nuts']::text[], 'main'::public.meal_role, 1, '/menu/b7a1d000-0000-4000-8000-000000000025/1152.webp', NULL, NULL, NULL, NULL)
